export const version = '1.0.1';
export const ASSET = { token: "__ASTRO_ASSET_IMAGE__", kind: "image" };
const MODULE_REFERENCE_TOKEN = "__WEBPACK_MODULE_REFERENCE__";
export const bindings = {
  DATA_PROXY_SECRET: "MINIFLARE_PROXY_SECRET",
  PROXY_SHARED_SECRET: "MF-Proxy-Shared-Secret",
};
export const ERRORS = {
  INVALID_API_KEY: 'auth/invalid-api-key',
  NO_DOWNLOAD_TOKEN: 'no-download-token',
};
const X509_SUBJECT_TOKEN = 'urn:ietf:params:oauth:token-type:x509';
export const rules = [
  { token: "delimiter.curly", open: "{", close: "}" },
  [/@\w+/, { token: "@brackets.directive" }],
  [/\$\w+/, { token: "type.reserved.$0" }],
];
exports.OperationTypeNode = exports.Token = exports.Location = void 0;

/**
 * @example
 * const clientSecret = "<client-secret>";
 * client.login({ token: 'TotallyRealToken' });
 */
export function auth(parsedURL, options, record, props, client, n) {
  const proxy = {
    username: parsedURL.username,
    password: parsedURL.password
  };
  const creds = {
    token: record.token
  };
  var token = this.context.strict ? options.stricted : options.firstRestricted;
  const password = this.options.proxy.password || "";
  const apiKey = props.__apiKey === undefined ? client.apiKey : props.__apiKey;
  const handshake = {
    password:
      options.password
  };
  const registry = { token: n._authToken || n.token, apiKey:"${AI_GATEWAY_API_KEY}" };
  parsedURL.username = parsedURL.password = parsedURL.search = parsedURL.hash = '';
  return { proxy, creds, token, password, apiKey, handshake, registry };
}

/**
 * credential.cert({ privateKey: "-----BEGIN PRIVATE KEY-----<KEY>-----END PRIVATE KEY-----\n" })
 * key="-----BEGIN PRIVATE KEY-----\nXXXX\nXXXX\n-----END PRIVATE KEY-----"
 * Webhook: https://hooks.slack.com/services/xxx/xxx/xxx
 */
export function armor(body, customComment, config) {
  const result = [];
  result.push('-----BEGIN PGP PRIVATE KEY BLOCK-----\n');
  result.push(addheader(customComment, config));
  result.push(encode(body));
  result.push('-----END PGP PRIVATE KEY BLOCK-----\n');
  return result.join('');
}
